package com.riskguard.transaction.config;
import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.web.cors.CorsConfiguration; import org.springframework.web.cors.CorsConfigurationSource; import org.springframework.web.cors.UrlBasedCorsConfigurationSource; import java.util.List;
@Configuration public class WebConfiguration { @Bean CorsConfigurationSource corsConfigurationSource(@Value("${app.cors.allowed-origins:http://localhost:5173}") String origins){List<String> allowed=List.of(origins.split(",")).stream().map(String::trim).filter(value -> !value.isBlank()).toList();if(allowed.isEmpty()||allowed.contains("*"))throw new IllegalStateException("CORS origins must be explicit when credentials are enabled");CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(allowed);c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type","Idempotency-Key","X-Correlation-Id"));c.setExposedHeaders(List.of("X-Correlation-Id"));c.setAllowCredentials(true);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} }
